// Generates src/brand-icons.ts: bundled offline logo paths for the brand
// registry in src/brands.ts, sourced from simple-icons at generation time.
// The generated file is committed, so the app carries no runtime dependency
// and never touches the network for icons.
// Usage: node scripts/gen-brand-icons.mjs
import { writeFileSync } from "node:fs";
import * as simpleIcons from "simple-icons";

// brand id in src/brands.ts -> candidate simple-icons slugs (first wins)
const WANTED = {
  aws: ["amazonwebservices", "aws"],
  amazon: ["amazon"],
  google: ["google"],
  microsoft: ["microsoft"],
  github: ["github"],
  gitlab: ["gitlab"],
  bitbucket: ["bitbucket"],
  atlassian: ["atlassian"],
  cloudflare: ["cloudflare"],
  discord: ["discord"],
  stripe: ["stripe"],
  paypal: ["paypal"],
  facebook: ["facebook"],
  instagram: ["instagram"],
  whatsapp: ["whatsapp"],
  telegram: ["telegram"],
  x: ["x"],
  reddit: ["reddit"],
  linkedin: ["linkedin"],
  twitch: ["twitch"],
  steam: ["steam"],
  apple: ["apple"],
  heroku: ["heroku"],
  digitalocean: ["digitalocean"],
  linode: ["linode", "akamai"],
  vultr: ["vultr"],
  hetzner: ["hetzner"],
  contabo: ["contabo"],
  interserver: ["interserver"],
  namecheap: ["namecheap"],
  godaddy: ["godaddy"],
  zoho: ["zoho"],
  okta: ["okta"],
  auth0: ["auth0"],
  proton: ["proton", "protonmail", "protonvpn"],
  binance: ["binance"],
  coinbase: ["coinbase"],
  kraken: ["kraken"],
  kucoin: ["kucoin"],
  pdax: ["pdax"],
  xendit: ["xendit"],
  skiff: ["skiff"],
  docker: ["docker"],
  npm: ["npm"],
  dropbox: ["dropbox"],
  slack: ["slack"],
  notion: ["notion"],
  figma: ["figma"],
  vercel: ["vercel"],
  openai: ["openai"],
  anthropic: ["anthropic", "claude"],
  yahoo: ["yahoo"],
};

// custom in-house marks (24x24 viewBox, drawn like the app logo).
// simple-icons dropped several brands for legal reasons (microsoft,
// amazon, linkedin, slack, openai, yahoo...); microsoft's four-square
// mark is geometric and bundled here, the rest fall back to monograms.
const CUSTOM = {
  // the PayShield shield silhouette from the app logo
  payshield: "M12 2l8 3v6c0 5-3.4 9.4-8 11-4.6-1.6-8-6-8-11V5l8-3z",
  // microsoft: four squares
  microsoft: "M3 3h8.5v8.5H3V3zm9.5 0H21v8.5h-8.5V3zM3 12.5h8.5V21H3v-8.5zm9.5 0H21V21h-8.5v-8.5z",
};

const bySlug = new Map();
for (const icon of Object.values(simpleIcons)) {
  if (icon && typeof icon.slug === "string" && typeof icon.path === "string") {
    bySlug.set(icon.slug, icon);
  }
}

const found = [];
const missing = [];
for (const [id, slugs] of Object.entries(WANTED)) {
  const icon = slugs.map((s) => bySlug.get(s)).find(Boolean);
  if (icon) found.push([id, icon.path]);
  else missing.push(id);
}

const lines = [
  "// GENERATED by scripts/gen-brand-icons.mjs — bundled offline logo",
  "// paths (24x24 viewBox) keyed by brand id from src/brands.ts.",
  "// Regenerate after changing the brand registry: node scripts/gen-brand-icons.mjs",
  "",
  "export const BRAND_ICONS: Readonly<Record<string, string>> = Object.freeze({",
  ...found.map(([id, path]) => `  ${id}: "${path}",`),
  ...Object.entries(CUSTOM).map(([id, path]) => `  ${id}: "${path}",`),
  "});",
  "",
];

writeFileSync("src/brand-icons.ts", lines.join("\n"));
console.log(`bundled ${found.length + Object.keys(CUSTOM).length} icons -> src/brand-icons.ts`);
if (missing.length > 0) {
  console.log(`no simple-icon for (monogram fallback): ${missing.join(", ")}`);
}
